import { existsSync, readdirSync } from 'node:fs';
import { join, dirname, basename } from 'node:path';
import sharp from 'sharp';

/**
 * Responsive image helper for the variants generated by tools/perf/optimize-images.mjs (npm run perf:images):
 *
 *   /img/work/ferox-b.webp  ->  /img/work/ferox-b-400.webp, /img/work/ferox-b-800.webp
 *   /images/uploads/liam.jpg ->  /images/uploads/liam.webp (master) + liam-500.webp
 *
 * Variants are looked up on disk at build time, so a missing file simply falls back to the original `src`
 * (no srcset). Components keep their own width/height/loading/decoding/classes and only spread the result.
 */
const PUBLIC = join(process.cwd(), 'public');
const cache = new Map<string, string[]>();

const files = (dir: string) => {
  let list = cache.get(dir);
  if (!list) {
    list = existsSync(join(PUBLIC, dir)) ? readdirSync(join(PUBLIC, dir)) : [];
    cache.set(dir, list);
  }
  return list;
};

export interface ResponsiveImage {
  src: string;
  srcset?: string;
  sizes?: string;
}

/**
 * @param src      public URL of the original, e.g. `/img/work/ferox-b.webp`
 * @param width    intrinsic width of the original (the largest candidate); read from the file when omitted
 * @param sizes    the `sizes` attribute (only emitted together with a srcset)
 */
export async function responsiveImage(src: string, sizes: string, width?: number): Promise<ResponsiveImage> {
  const dir = dirname(src);
  const name = basename(src).replace(/\.[a-z0-9]+$/i, '');
  const list = files(dir);
  // a jpg/png original may ship a webp master with the same name: that is the largest candidate
  const master = /\.webp$/i.test(src) || !list.includes(`${name}.webp`) ? src : `${dir}/${name}.webp`;
  if (!width) width = (await sharp(join(PUBLIC, master)).metadata()).width ?? 0;
  const max = width;
  const variants = list
    .map((f) => f.match(new RegExp(`^${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}-(\\d+)\\.webp$`)))
    .filter((m): m is RegExpMatchArray => !!m && Number(m[1]) < max)
    .map((m) => ({ w: Number(m[1]), url: `${dir}/${m[0]}` }))
    .sort((a, b) => a.w - b.w);
  if (!variants.length) return { src: master };
  const srcset = [...variants.map((v) => `${v.url} ${v.w}w`), `${master} ${max}w`].join(', ');
  return { src: master, srcset, sizes };
}
